async function getDunningStatus(subscriptionId) {
  const db2 = await getDb();
  if (!db2) return null;
  const retries = await db2.select().from(paymentRetries).where(eq3(paymentRetries.subscriptionId, subscriptionId)).orderBy(desc2(paymentRetries.createdAt));
  const events = await db2.select().from(dunningEvents).where(eq3(dunningEvents.subscriptionId, subscriptionId)).orderBy(desc2(dunningEvents.createdAt)).limit(50);
  const retryCount = retries.length;
  const latestRetry = retries[0] || null;
  const isDunning = retries.some((retry) => ["pending", "processing", "failed"].includes(retry.status));
  const nextRetryAt = latestRetry?.nextRetryAt ?? null;
  const overdueDays = latestRetry?.attemptedAt ? Math.max(0, Math.floor((Date.now() - new Date(latestRetry.attemptedAt).getTime()) / (1e3 * 60 * 60 * 24))) : 0;
  const dunningPhase = !isDunning ? "none" : latestRetry?.status === "pending" ? "early" : latestRetry?.status === "failed" ? "late" : "late";
  return {
    subscriptionId,
    isDunning,
    overdueDays,
    retryCount,
    nextRetryAt,
    dunningPhase,
    events
  };
}
