function generateCSVTemplate(module) {
  const columns = moduleTemplates[module];
  if (!columns) {
    throw new Error(`Unknown module: ${module}`);
  }
  const headers = columns.map((col) => {
    const required = col.required ? "*" : "";
    const type = ` [${col.type}]`;
    return `${col.name}${required}${type}`;
  });
  const descriptions = columns.map((col) => col.description || "");
  const lines = [
    "# Import Template for " + module,
    "# Fields marked with * are required",
    "# Column descriptions: " + descriptions.map(
      (description, index8) => `${columns[index8].name}=${description || columns[index8].type}`
    ).join(" | "),
    headers.join(",")
  ];
  return lines.join("\n");
}
function parseCSV(csvContent) {
  const lines = csvContent.split(/\r?\n/).filter((line) => !line.trimStart().startsWith("#") && line.trim());
  if (lines.length < 2) {
    throw new Error("CSV file must have headers and at least one data row");
  }
  const headers = parseCSVLine(lines[0]).map((h) => {
    const normalized = h.replace(/\[.*?\]/g, "").replace(/\*/g, "").trim();
    return legacyColumnAliases[normalized] ?? normalized;
  });
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const values = parseCSVLine(lines[i]);
    const row = {};
    headers.forEach((header, idx) => {
      let value = values[idx] || "";
      if (value === "" || value === "null" || value === "undefined") {
        row[header] = null;
      } else if (value === "true") {
        row[header] = true;
      } else if (value === "false") {
        row[header] = false;
      } else if (!isNaN(Number(value)) && value !== "") {
        row[header] = Number(value);
      } else {
        row[header] = value;
      }
    });
    rows.push(row);
  }
  return rows;
}
function parseCSVLine(line) {
  const values = [];
  let value = "";
  let quoted = false;
  for (let index8 = 0; index8 < line.length; index8++) {
    const char = line[index8];
    const next = line[index8 + 1];
    if (char === '"' && quoted && next === '"') {
      value += '"';
      index8++;
    } else if (char === '"') {
      quoted = !quoted;
    } else if (char === "," && !quoted) {
      values.push(value.trim());
      value = "";
    } else {
      value += char;
    }
  }
  values.push(value.trim());
  return values;
}
