    if (!org2) {
      throw new TRPCError57({
        code: "NOT_FOUND",
        message: "Organization not found"
      });
    }
    const members = await db2.select({
      id: users.id,
      email: users.email,
      name: users.name,
      role: users.role,
      createdAt: users.createdAt
    }).from(users).where(eq108(users.organizationId, organizationId));
