    runMrp: protectedProcedure.input(z100.object({ horizonDate: z100.string(), safetyStock: z100.number().int().nonnegative().default(0), recommendations: z100.array(z100.object({ productId: z100.string(), requiredDate: z100.string(), quantity: z100.number().int().positive(), sourceType: z100.string(), sourceId: z100.string().optional() })).default([]) })).mutation(async ({ ctx, input }) => {
      const generated = input.recommendations.length ? input.recommendations : (await database().query("SELECT p.id productId,p.stockQuantity,COALESCE(SUM(r.quantity),0) reserved FROM products p LEFT JOIN inventory_reservations r ON r.productId=p.id AND r.organizationId=? AND r.status='reserved' WHERE p.organizationId=? GROUP BY p.id,p.stockQuantity", [org(ctx), org(ctx)]))[0].flatMap((row) => {
        const quantity = Math.max(0, Number(input.safetyStock) + Number(row.reserved || 0) - Number(row.stockQuantity || 0));
        return quantity > 0 ? [{ productId: row.productId, requiredDate: input.horizonDate, quantity, sourceType: "stock_and_reservations" }] : [];
      });
      const runId = id("mrp");
      const pool13 = database();
      const connection = await pool13.getConnection();
      try {
        await connection.beginTransaction();
        await connection.query("INSERT INTO mrp_runs (id,organizationId,runDate,horizonDate,status,createdBy) VALUES (?,?,NOW(),?,'completed',?)", [runId, org(ctx), input.horizonDate, ctx.user.id]);
        for (const recommendation of generated) await connection.query("INSERT INTO mrp_recommendations (id,runId,productId,requiredDate,quantity,sourceType,sourceId) VALUES (?,?,?,?,?,?,?)", [id("mrp_rec"), runId, recommendation.productId, recommendation.requiredDate, recommendation.quantity, recommendation.sourceType, recommendation.sourceId || null]);
        await connection.commit();
      } catch (error) {
        await connection.rollback();
        throw error;
      } finally {
        connection.release();
      }
      return { id: runId, status: "completed", recommendations: generated };
    }),
