      if (params.userId) conditions.push(sql35`userId = ${params.userId}`);
      if (params.entityType) conditions.push(sql35`entityType = ${params.entityType}`);
      if (params.action) conditions.push(sql35`action = ${params.action}`);
      if (params.search) conditions.push(sql35`description LIKE ${`%${params.search}%`}`);
      if (params.startDate) conditions.push(sql35`createdAt >= ${params.startDate}`);
      if (params.endDate) conditions.push(sql35`createdAt <= ${params.endDate}`);
      const whereClause = conditions.length > 0 ? sql35`WHERE ${sql35.join(conditions, sql35` AND `)}` : sql35``;
      const fromClause = buildActivityLogFromClause(ctx);
