async function calculateP9Data(input) {
  const pool13 = getPool();
  if (!pool13) return null;
  try {
    const [empRows] = await pool13.query(
      `SELECT id, firstName, lastName, email, taxId FROM employees WHERE id = ? AND organizationId = ? LIMIT 1`,
      [input.employeeId, input.organizationId]
    );
    const emp = empRows?.[0];
    if (!emp) return null;
    const [taxRows] = await pool13.query(
      `SELECT taxNumber FROM employeeTaxInfo WHERE employeeId = ? ORDER BY effectiveDate DESC LIMIT 1`,
      [input.employeeId]
    );
    const taxInfo = taxRows?.[0];
    const taxNumber = taxInfo?.taxNumber || emp.taxId || "N/A";
    const [payslipRows] = await pool13.query(
      `SELECT 
        COUNT(*) as numberOfPayslips,
        SUM(basicSalary) as totalBasic,
        SUM(allowances) as totalAllowances,
        SUM(grossSalary) as totalGross,
        SUM(paye) as totalPaye,
        SUM(nssf) as totalNssf,
        SUM(shif) as totalShif,
        SUM(housingLevy) as totalHousingLevy,
        SUM(netSalary) as totalNet
       FROM payslips
       WHERE employeeId = ? AND organizationId = ? AND YEAR(payPeriodEnd) = ?`,
      [input.employeeId, input.organizationId, input.taxYear]
    );
    const payslips3 = payslipRows?.[0];
    if (!payslips3) {
      console.warn(
        `[P9-GEN] No payslips found for employee ${emp.email} in ${input.taxYear}`
      );
      return null;
    }
    const grossIncome = payslips3.totalGross || 0;
    const paye = payslips3.totalPaye || 0;
    const nssf = payslips3.totalNssf || 0;
    const shif = payslips3.totalShif || 0;
    const housingLevy = payslips3.totalHousingLevy || 0;
    const reliefs = 0;
    const totalDeductions = paye + nssf + shif + housingLevy;
    const netTaxPayable = paye - reliefs;
    return {
      employeeId: input.employeeId,
      organizationId: input.organizationId,
      taxYear: input.taxYear,
      taxNumber,
      grossIncome,
      paye,
      nssf,
      shif,
      housingLevy,
      reliefs,
      netTaxPayable,
      numberOfPayslips: payslips3.numberOfPayslips || 0
    };
  } catch (error) {
    console.error("[P9-GEN] Error calculating P9 data:", error);
    return null;
  }
}
