      [id2, ctx.user.organizationId, input.name, input.description || null, input.category || null, input.trainer || null, input.startDate || null, input.endDate || null, input.maxParticipants || null, input.cost || null, input.location || null, input.isOnline ? 1 : 0, input.isMandatory ? 1 : 0, ctx.user.id]
