// server/lib/paymentWebhooks.ts
function setupPaymentWebhooks(app) {
  app.post(
    "/api/webhooks/stripe",
    // Use raw body parser ONLY for this endpoint to preserve raw bytes for signature verification
    (req, res, next) => {
      let data = "";
      req.on("data", (chunk) => {
        data += chunk.toString();
      });
      req.on("end", () => {
        try {
          req.body = JSON.parse(data);
          req.rawBody = data;
          next();
        } catch (error) {
          return res.status(400).json({ error: "Invalid JSON in webhook body" });
        }
      });
    },
    async (req, res) => {
      try {
        const signature = req.headers["stripe-signature"];
        if (!signature) {
          return res.status(400).json({ error: "Missing stripe-signature header" });
        }
        const result = await handleWebhookEvent(
          req.rawBody,
          signature
        );
        console.log("[Webhook] Stripe event processed:", {
          eventType: result.eventType,
          invoiceId: result.invoiceId,
          processed: result.processed
        });
        res.status(200).json({ received: true, processed: result.processed });
      } catch (error) {
        console.error("[Webhook] Stripe webhook error:", error);
        if (error instanceof Error && error.message.includes("signature")) {
          return res.status(400).json({ error: "Invalid signature" });
        }
        res.status(500).json({ error: "Webhook processing failed" });
      }
    }
  );
  app.post("/api/webhooks/mpesa", async (req, res) => {
    try {
      const result = await handleCallback(req.body);
      console.log("[Webhook] M-Pesa callback processed:", {
        checkoutRequestId: result.checkoutRequestId,
        status: result.status
      });
      res.status(200).json({
        ResultCode: 0,
        ResultDesc: "Accepted"
      });
    } catch (error) {
      console.error("[Webhook] M-Pesa webhook error:", error);
      res.status(200).json({
        ResultCode: 1,
        ResultDesc: "Error processing callback"
      });
    }
  });
  app.post("/api/webhooks/mpesa-validation", (req, res) => {
    try {
      res.status(200).json({
        ResultCode: 0,
        ResultDesc: "Validation successful"
      });
    } catch (error) {
      console.error("[Webhook] M-Pesa validation error:", error);
      res.status(200).json({
        ResultCode: 0,
        ResultDesc: "Validation processed"
      });
    }
  });
  app.get("/api/webhooks/health", (req, res) => {
    res.status(200).json({
      status: "ok",
      timestamp: (/* @__PURE__ */ new Date()).toISOString(),
      endpoints: {
        stripe: "/api/webhooks/stripe",
        mpesa: "/api/webhooks/mpesa",
        mpesaValidation: "/api/webhooks/mpesa-validation"
      }
    });
  });
}

// server/_core/vite.ts
import express from "express";
import fs6 from "fs";
import { nanoid as nanoid10 } from "nanoid";
import path6 from "path";
import { pathToFileURL } from "url";
async function setupVite(app, server) {
  const { createServer: createViteServer } = await import("vite");
  const viteConfigPath = path6.resolve(process.cwd(), "vite.config.ts");
  const { default: viteConfig } = await import(pathToFileURL(viteConfigPath).href);
  const serverOptions = {
    middlewareMode: true,
    hmr: { server },
    allowedHosts: true
  };
  const vite = await createViteServer({
    ...viteConfig,
    configFile: false,
    server: serverOptions,
    appType: "custom"
  });
  app.use(vite.middlewares);
  app.use("*", async (req, res, next) => {
    const url = req.originalUrl;
    try {
      const clientTemplate = path6.resolve(
        import.meta.dirname,
        "../..",
        "client",
        "index.html"
      );
      let template = await fs6.promises.readFile(clientTemplate, "utf-8");
      template = template.replace(
        `src="/src/main.tsx"`,
        `src="/src/main.tsx?v=${nanoid10()}"`
      );
      const page = await vite.transformIndexHtml(url, template);
      res.status(200).set({ "Content-Type": "text/html" }).end(page);
    } catch (e) {
      vite.ssrFixStacktrace(e);
      next(e);
    }
  });
}
function serveStatic(app) {
  const possiblePaths = [
    // Absolute path based on process.cwd()
    path6.join(process.cwd(), "dist", "public"),
    // Relative to this file's directory (in unbundled development)
    path6.resolve(import.meta.dirname, "../..", "dist", "public"),
    // Absolute path for Docker container
    "/app/dist/public"
  ];
  let distPath = possiblePaths[0];
  for (const p of possiblePaths) {
    if (fs6.existsSync(p)) {
      distPath = p;
      console.log(`[Static] Serving assets from: ${distPath}`);
      break;
    }
  }
  if (!fs6.existsSync(distPath)) {
    console.error(
      `Could not find the build directory. Tried:`,
      possiblePaths.join(", "),
      `Make sure to build the client first`
    );
  }
  app.use(express.static(distPath, { extensions: ["html"], dotfiles: "allow" }));
  app.get("*", (req, res) => {
    const p = req.path || req.url || "";
    if (p.startsWith("/api") || p === "/api") {
      res.status(404).json({
        error: {
          code: "NOT_FOUND",
          message: "API route not found",
          path: p
        }
      });
      return;
    }
    if (path6.extname(p) || p.startsWith("/assets/") || p.startsWith("/src/")) {
      res.status(404).end();
      return;
    }
    res.sendFile(path6.resolve(distPath, "index.html"));
  });
}

